class Solution:
    def maxDiff(self, num: int) -> int:
        s = str(num)

        # Maximum
        a = list(s)
        if a[0] != '9':
            x = a[0]
            a = ['9' if c == x else c for c in a]
        else:
            x = next((c for c in a if c != '9'), None)
            if x is not None:
                a = ['9' if c == x else c for c in a]

        # Minimum
        b = list(s)
        if b[0] != '1':
            x = b[0]
            b = ['1' if c == x else c for c in b]
        else:
            x = next((c for c in b[1:] if c not in ('0', '1')), None)
            if x is not None:
                b = ['0' if c == x else c for c in b]

        return int(''.join(a)) - int(''.join(b))

