import java.io.*;
import java.util.*;

class Solution {
    public int maxDiff(int num) {
        String s = String.valueOf(num);

        char[] max = s.toCharArray();
        char maxTarget = 0;
        if (max[0] != '9') {
            maxTarget = max[0];
        } else {
            for (char c : max) {
                if (c != '9') { maxTarget = c; break; }
            }
        }
        if (maxTarget != 0) {
            for (int i = 0; i < max.length; i++) {
                if (max[i] == maxTarget) max[i] = '9';
            }
        }

        char[] min = s.toCharArray();
        char minTarget = 0;
        char minReplacement;
        if (min[0] != '1') {
            minTarget = min[0];
            minReplacement = '1';
        } else {
            minReplacement = '0';
            for (int i = 1; i < min.length; i++) {
                if (min[i] != '0' && min[i] != '1') {
                    minTarget = min[i];
                    break;
                }
            }
        }
        if (minTarget != 0) {
            for (int i = 0; i < min.length; i++) {
                if (min[i] == minTarget) min[i] = minReplacement;
            }
        }

        return Integer.parseInt(new String(max)) - Integer.parseInt(new String(min));
    }
}

