        string b = s;
        char minTarget = 0, replacement = '1';
        if (b[0] != '1') {
            minTarget = b[0];
        } else {
            replacement = '0';
            for (int i = 1; i < (int)b.size(); ++i) {
                if (b[i] != '0' && b[i] != '1') {
                    minTarget = b[i];
                    break;
