var maxDiff = function(num) {
    const s = String(num);

    const a = s.split('');
    let target = null;
    if (a[0] !== '9') target = a[0];
    else target = a.find(c => c !== '9') ?? null;
    if (target !== null) {
        for (let i = 0; i < a.length; i++) {
            if (a[i] === target) a[i] = '9';
        }
    }

    const b = s.split('');
    let minTarget = null;
    let replacement = '1';
    if (b[0] !== '1') {
        minTarget = b[0];
    } else {
        replacement = '0';
        for (let i = 1; i < b.length; i++) {
            if (b[i] !== '0' && b[i] !== '1') {
                minTarget = b[i];
                break;
            }
        }
    }
    if (minTarget !== null) {
        for (let i = 0; i < b.length; i++) {
            if (b[i] === minTarget) b[i] = replacement;
        }
    }

    return Number(a.join('')) - Number(b.join(''));
}

