#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int maxDiff(int num) {
    char s[16];
    sprintf(s, "%d", num);

    char a[16], b[16];
    strcpy(a, s);
    strcpy(b, s);

    char target = 0;
    if (a[0] != '9') target = a[0];
    else {
        for (int i = 0; a[i]; ++i) {
            if (a[i] != '9') { target = a[i]; break; }
        }
    }
    if (target) {
        for (int i = 0; a[i]; ++i)
            if (a[i] == target) a[i] = '9';
    }

    char minTarget = 0, replacement = '1';
    if (b[0] != '1') {
        minTarget = b[0];
    } else {
        replacement = '0';
        for (int i = 1; b[i]; ++i) {
            if (b[i] != '0' && b[i] != '1') {
                minTarget = b[i];
                break;
            }
        }
    }
    if (minTarget) {
        for (int i = 0; b[i]; ++i)
            if (b[i] == minTarget) b[i] = replacement;
    }

    return atoi(a) - atoi(b);
}

